export interface TestbedHandler {
  echo(message: string): Promise<string> | string;
  reverse(message: string): Promise<string> | string;
  divide(
    dividend: bigint,
    divisor: bigint,
  ): Promise<{ ok: true; value: bigint } | { ok: false; error: MathError }> | { ok: true; value: bigint } | {
    ok: false;
    error: MathError;
  };
  lookup(
    id: number,
  ): Promise<{ ok: true; value: Person } | { ok: false; error: LookupError }> | { ok: true; value: Person } | {
    ok: false;
    error: LookupError;
  };
  sum(numbers: unknown): Promise<bigint> | bigint;
  generate(count: number, output: unknown): Promise<void> | void;
  generateRetryNonIdem(count: number, output: unknown): Promise<void> | void;
  generateRetryIdem(count: number, output: unknown): Promise<void> | void;
  transform(input: unknown, output: unknown): Promise<void> | void;
  postReplyGenerate(output: unknown): Promise<void> | void;
  postReplySum(input: unknown, result: unknown): Promise<void> | void;
  echoPoint(point: Point): Promise<Point> | Point;
  createPerson(name: string, age: number, email: string | null): Promise<Person> | Person;
  rectangleArea(rect: Rectangle): Promise<number> | number;
  parseColor(name: string): Promise<Color | null> | Color | null;
  shapeArea(shape: Shape): Promise<number> | number;
  createCanvas(name: string, shapes: Shape[], background: Color): Promise<Canvas> | Canvas;
  echoGnarly(payload: GnarlyPayload): Promise<GnarlyPayload> | GnarlyPayload;
  processMessage(msg: Message): Promise<Message> | Message;
  getPoints(count: number): Promise<Point[]> | Point[];
  swapPair(pair: [number, string]): Promise<[string, number]> | [string, number];
  echoBytes(data: Uint8Array): Promise<Uint8Array> | Uint8Array;
  echoBool(b: boolean): Promise<boolean> | boolean;
  echoU64(n: bigint): Promise<bigint> | bigint;
  echoOptionString(s: string | null): Promise<string | null> | string | null;
  sumLarge(numbers: unknown): Promise<bigint> | bigint;
  generateLarge(count: number, output: unknown): Promise<void> | void;
  allColors(): Promise<Color[]> | Color[];
  describePoint(label: string, x: number, y: number, active: boolean): Promise<TaggedPoint> | TaggedPoint;
  echoShape(shape: Shape): Promise<Shape> | Shape;
  echoStatusV1(status: Status): Promise<Status> | Status;
  echoTagV1(tag: Tag): Promise<Tag> | Tag;
  echoProfile(profile: Profile): Promise<Profile> | Profile;
  echoRecord(record: Record): Promise<Record> | Record;
  echoStatus(status: Status): Promise<Status> | Status;
  echoTag(tag: Tag): Promise<Tag> | Tag;
  echoMeasurement(m: Measurement): Promise<Measurement> | Measurement;
  echoConfig(c: Config): Promise<Config> | Config;
}

